// One output item per PDF attachment. Images (logos, signatures) and other files are skipped.
const out = [];
$input.all().forEach((item, index) => {
  const email = item.json;
  const files = item.binary || {};
  for (const [key, file] of Object.entries(files)) {
    const name = (file.fileName || '').toLowerCase();
    const isPdf = file.mimeType === 'application/pdf' || name.endsWith('.pdf');
    if (!isPdf) continue;
    out.push({
      json: {
        messageId: email.id,
        from: email.from?.value?.[0]?.address || email.from?.text || '',
        subject: email.subject || '',
        receivedAt: email.date || '',
        fileName: file.fileName || `${key}.pdf`,
      },
      binary: { data: file },
      pairedItem: { item: index },
    });
  }
});
return out;

// Turn each uploaded PDF into one item per invoice.
// If splitting is off, failed, or found a single invoice, the whole file is one invoice.
const context = $('Attach upload URL').all();
const results = $input.all();
const out = [];

for (let i = 0; i < results.length; i++) {
  const ctx = context[i]?.json || {};
  const res = results[i].json || {};
  let urls = [];

  const list = res.urls ?? res.body?.urls ?? res.body;
  if (Array.isArray(list)) {
    urls = list.flat();
  } else if (typeof res.url === 'string' && res.url !== ctx.url) {
    if (/\.json(\?|$)/i.test(res.url)) {
      // Some PDF.co jobs return a JSON file that lists the output URLs.
      try {
        const data = await this.helpers.httpRequest({ url: res.url, json: true });
        urls = Array.isArray(data) ? data : (data?.urls || []);
      } catch (e) { urls = []; }
    } else {
      urls = res.url.split(',');
    }
  }

  urls = urls
    .map(u => (typeof u === 'string' ? u.trim() : u?.url))
    .filter(u => typeof u === 'string' && /^https?:\/\//.test(u));
  if (!urls.length && ctx.url) urls = [ctx.url];

  const base = {
    messageId: ctx.messageId,
    from: ctx.from,
    subject: ctx.subject,
    receivedAt: ctx.receivedAt,
    fileName: ctx.fileName,
  };

  if (!urls.length) {
    out.push({ json: { ...base, invoiceUrl: '', part: 1, parts: 1, stageError: 'The PDF could not be uploaded to PDF.co' } });
    continue;
  }
  urls.forEach((url, k) => out.push({ json: { ...base, invoiceUrl: url, part: k + 1, parts: urls.length } }));
}
return out;

// Check each parsed invoice, catch duplicates, and decide whether it is logged or sent for review.
const cfg = $('Config').first().json;
// Every invoice collected by the loop (its "done" output).
const invoices = $('Loop over invoices').all(0);
const logged = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);

const key = (vendor, no) => `${String(vendor || '').trim().toLowerCase()}|${String(no || '').trim().toLowerCase()}`;
const seen = new Set(logged.map(r => key(r['Vendor'], r['Invoice Number'])));

const toNumber = (value) => {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return value;
  let s = String(value).replace(/[^0-9.,-]/g, '');
  if (s.includes(',') && s.includes('.')) {
    s = s.lastIndexOf(',') > s.lastIndexOf('.') ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (/,\d{1,2}$/.test(s)) {
    s = s.replace(',', '.');
  } else {
    s = s.replace(/,/g, '');
  }
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : null;
};

const flattenLines = (lines) => {
  if (!Array.isArray(lines)) return [];
  return lines.flat(Infinity).filter(l => l && typeof l === 'object');
};
const pick = (obj, names) => {
  for (const n of names) if (obj[n] !== undefined && obj[n] !== '') return obj[n];
  return '';
};

const today = new Date();
today.setHours(0, 0, 0, 0);
const alertAmount = Number(cfg.highTotalAmount) || 0;
const dueSoonDays = Number(cfg.dueSoonDays) || 0;
const gmailLink = (id) => (id ? `https://mail.google.com/mail/u/0/#all/${id}` : '');

return invoices.map(({ json: j }) => {
  const body = j.body && typeof j.body === 'object' && !Array.isArray(j.body) ? j.body : null;
  const b = body || {};
  const vendor = b.vendor?.name || '';
  const invoiceNo = b.invoice?.invoiceNo || '';
  const pay = b.paymentDetails || {};
  const total = toNumber(pay.total);
  const lines = flattenLines(b.lineItems).map((l, n) => ({
    'Invoice Number': invoiceNo,
    'Vendor': vendor,
    'Line': n + 1,
    'Description': pick(l, ['description', 'itemDescription', 'item', 'name', 'product']),
    'Quantity': toNumber(pick(l, ['quantity', 'qty'])) ?? pick(l, ['quantity', 'qty']),
    'Unit Price': toNumber(pick(l, ['unit_price', 'unitPrice', 'price', 'rate'])) ?? '',
    'Amount': toNumber(pick(l, ['total', 'amount', 'lineTotal', 'line_total'])) ?? '',
  }));

  const reasons = [];
  if (j.stageError) {
    reasons.push(j.stageError);
  } else if (!body) {
    reasons.push('PDF.co could not read this file as an invoice');
  } else {
    if (!invoiceNo) reasons.push('Missing invoice number');
    if (total === null) reasons.push('Missing or unreadable total');
    const k = key(vendor, invoiceNo);
    if (invoiceNo && seen.has(k)) reasons.push(`Duplicate: ${vendor || 'this vendor'} #${invoiceNo} is already logged`);
    if (invoiceNo) seen.add(k);
  }

  const alerts = [];
  let daysUntilDue = null;
  const dueText = String(pay.dueDate || '').trim();
  const due = Date.parse(/^\d{4}-\d{2}-\d{2}$/.test(dueText) ? `${dueText}T00:00:00` : dueText);
  if (!Number.isNaN(due)) {
    daysUntilDue = Math.round((new Date(due).setHours(0, 0, 0, 0) - today) / 86400000);
  }
  if (!reasons.length) {
    if (alertAmount && total !== null && total >= alertAmount) alerts.push(`Total ${pay.total} is at or above ${alertAmount}`);
    if (daysUntilDue !== null && daysUntilDue < 0) alerts.push(`Overdue by ${-daysUntilDue} day(s)`);
    else if (daysUntilDue !== null && daysUntilDue <= dueSoonDays) alerts.push(`Due in ${daysUntilDue} day(s)`);
  }

  const status = reasons.length ? 'review' : 'ok';
  const label = invoiceNo ? `${vendor || 'Unknown vendor'} #${invoiceNo}` : j.fileName;
  const partNote = j.parts > 1 ? ` (invoice ${j.part} of ${j.parts} in the file)` : '';
  const alertSubject = status === 'review'
    ? `Invoice needs review: ${label}`
    : `Invoice alert: ${label}`;
  const alertBody = [
    status === 'review' ? 'This invoice was NOT logged and needs a manual check.' : 'This invoice was logged and matches an alert rule.',
    '',
    ...(status === 'review' ? reasons : alerts).map(r => `- ${r}`),
    '',
    `File: ${j.fileName}${partNote}`,
    `Vendor: ${vendor || 'not found'}`,
    `Invoice number: ${invoiceNo || 'not found'}`,
    `Total: ${pay.total || 'not found'}`,
    `Due date: ${pay.dueDate || 'not found'}`,
    `From: ${j.from}`,
    `Email subject: ${j.subject}`,
    `Open the email: ${gmailLink(j.messageId)}`,
  ].join('\n');

  return {
    json: {
      status,
      reasons: reasons.join('; '),
      hasAlert: alerts.length > 0,
      alerts: alerts.join('; '),
      alertSubject,
      alertBody,
      messageId: j.messageId,
      row: {
        'Invoice Number': invoiceNo,
        'Vendor': vendor,
        'Invoice Date': b.invoice?.invoiceDate || '',
        'Due Date': pay.dueDate || '',
        'Subtotal': toNumber(pay.subtotal) ?? '',
        'Tax': toNumber(pay.tax) ?? '',
        'Total': total ?? '',
        'PO Number': b.invoice?.poNo || '',
        'Line Items': lines.length,
        'Alerts': alerts.join('; '),
        'From': j.from,
        'Email Subject': j.subject,
        'Received At': j.receivedAt,
        'Source File': j.fileName + partNote,
        'Email Link': gmailLink(j.messageId),
        'Logged At': new Date().toISOString(),
      },
      lineItems: lines,
    },
  };
});
